const BY_LOCALE: Record<string, Record<string, ServiceContent>> = { ru, uz, en, tr, zh };

export function getServiceContent(locale: string, key: string): ServiceContent | null {
  return BY_LOCALE[locale]?.[key] ?? null;
}
